<?php
defined('ABSPATH') || exit;
/** Read-only adapter. No Research status, source, timer or checkpoint writes. */
function cdca_selected_evidence($id){
 cdca_need(cdca_stage()&&is_int($id)&&$id>0,'research_identity');global $wpdb;$p=$wpdb->prefix.'cdra_';$row=$wpdb->get_row($wpdb->prepare("SELECT i.id,i.content_hash,i.editorial_status,i.approved_hash,d.topic_id FROM {$p}items i JOIN {$p}discovery d ON d.item_id=i.id WHERE i.id=%d",$id),ARRAY_A);
 cdca_need($row&&$row['editorial_status']==='ready_for_content_agent'&&hash_equals((string)$row['content_hash'],(string)$row['approved_hash']),'research_not_selected');
 $rows=$wpdb->get_results($wpdb->prepare("SELECT i.id,i.payload,i.content_hash FROM {$p}items i JOIN {$p}discovery d ON d.item_id=i.id WHERE d.topic_id=%s ORDER BY i.id LIMIT 21",$row['topic_id']),ARRAY_A);cdca_need(!$wpdb->last_error&&count($rows)>=1&&count($rows)<=20,'research_topic_bounds');$sources=[];$cves=[];$hashes=[];$subject='';
 foreach($rows as $i=>$r){$v=json_decode($r['payload'],true,64,JSON_THROW_ON_ERROR);$url=$v['canonical_url'];cdca_need(is_string($url)&&filter_var($url,FILTER_VALIDATE_URL)&&str_starts_with($url,'https://'),'research_source_url');$sources[]=['id'=>'S'.($i+1),'url'=>$url,'publisher'=>$v['publisher']??$v['source'],'published'=>$v['published'],'title'=>mb_substr(wp_strip_all_tags($v['original_title']),0,500),'summary'=>mb_substr(wp_strip_all_tags($v['summary']),0,3000),'content_hash'=>$r['content_hash']];$hashes[]=[(int)$r['id'],$r['content_hash']];$cves=array_merge($cves,$v['cve_ids']);if((int)$r['id']===$id){$subject=$v['original_title'];}}
 $fresh=$wpdb->get_row($wpdb->prepare("SELECT i.content_hash,i.approved_hash,i.editorial_status,d.topic_id FROM {$p}items i JOIN {$p}discovery d ON d.item_id=i.id WHERE i.id=%d",$id),ARRAY_A);cdca_need($fresh&&$fresh['editorial_status']==='ready_for_content_agent'&&$fresh['content_hash']===$row['content_hash']&&$fresh['approved_hash']===$row['approved_hash']&&$fresh['topic_id']===$row['topic_id'],'research_changed');
 return ['topic_id'=>$row['topic_id'],'research_item'=>$id,'source_hash'=>cdca_hash([$row['topic_id'],$id,$hashes]),'subject'=>$subject,'sources'=>$sources,'cves'=>array_values(array_unique($cves)),'limitations'=>['Feed metadata/abstract excerpts only; not full article evidence.','Narrative assertions, dates, quotes and scientific validity require primary-source review.']];
}
function cdca_research_current($job){if((int)$job['is_test']){return true;}try{$now=cdca_selected_evidence((int)$job['research_item']);return hash_equals($job['source_hash'],$now['source_hash']);}catch(Throwable $e){return false;}}
